    @Override
    public InterfaceDTO getDados() { // metodo getDados é chamado para salvar os dados
        TelefoneDTO telefoneDTO = dto; // Usa a mesma instância do DTO atual que está sendo usado no painel

        // Lê os campos da tela, remove espaços extras
        telefoneDTO.ddd = jtfDDD.getText().trim();
        telefoneDTO.numero = jtfNumero.getText().trim();

        return telefoneDTO; // Retorna o dto atualizado para que o Controller use
    }

    @Override
    public void setDTO(InterfaceDTO dto) { //setDTO é chamado para preencher o painel com dados já existentes
        this.dto = (TelefoneDTO) dto; // Cast - Converte o InterfaceDTO para TelefoneDTO
        jtfDDD.setText(this.dto.ddd);
        jtfNumero.setText(this.dto.numero);
    }

